        ["goals.title"] = ["Goals", "Goals", "Hedefler", "Obiettivi"],
        ["goals.subtitle"] = ["Ein Ziel in Won. Was die Läufe einbringen, zählt die App selbst; Ausgaben und Zusatzeinnahmen trägst du ein.", "A goal in won. The app counts what the runs bring in; you enter expenses and extra income.", "Won cinsinden bir hedef. Koşuların getirisini uygulama sayar; giderleri ve ek geliri sen girersin.", "Un obiettivo in won. L’app conta ciò che portano i run; spese ed entrate extra le inserisci tu."],
        ["goals.none"] = ["Noch kein Ziel. Trag oben eins ein – zum Beispiel 1500w für den nächsten Kauf.", "No goal yet. Enter one above – say 1500w for your next purchase.", "Henüz hedef yok. Yukarıdan bir tane gir – örneğin bir sonraki alım için 1500w.", "Ancora nessun obiettivo. Inseriscine uno sopra – per esempio 1500w per il prossimo acquisto."],
