        ["goals.run"] = ["Aktiver Lauf", "Active run", "Aktif koşu", "Run attivo"],
        ["goals.run.note"] = ["Nur für die Anzeige und die Schätzung – in den Gewinn zählen alle Läufe seit dem Start des Ziels.", "For display and the estimate only – all runs since the goal started count towards the profit.", "Yalnızca gösterim ve tahmin için – kazanca hedefin başlangıcından beri tüm koşular sayılır.", "Solo per la visualizzazione e la stima – nel guadagno contano tutti i run dall’inizio dell’obiettivo."],
