        ["settings.stream.goal.hint"] = ["Eigene Datei „goal.html“ – eine zweite Browser-Quelle in OBS, unabhängig von der ersten Karte.", "Its own file “goal.html” – a second browser source in OBS, independent of the first card.", "Kendi dosyası “goal.html” – OBS’de ilk karttan bağımsız ikinci bir tarayıcı kaynağı.", "File proprio «goal.html» – una seconda sorgente browser in OBS, indipendente dalla prima scheda."],
