        ["settings.stream"] = ["Stream-Einblendung", "Stream overlay", "Yayın bilgi kutusu", "Overlay per lo stream"],
        ["settings.stream.enabled"] = ["Zahlen für OBS schreiben", "Write the numbers for OBS", "Sayıları OBS için yaz", "Scrivi i numeri per OBS"],
        ["settings.stream.hint"] = ["M2Hub legt die Zahlen als Dateien ab – kein Server, kein Port. In OBS entweder „overlay.html“ als Browser-Quelle (durchsichtiger Hintergrund, Aussehen wie die App) oder die einzelnen .txt als Text-Quelle mit „aus Datei lesen“.", "M2Hub writes the numbers to files – no server, no port. In OBS use either “overlay.html” as a browser source (transparent background, looks like the app) or the single .txt files as text sources with “read from file”.", "M2Hub sayıları dosyalara yazar – sunucu yok, port yok. OBS’de ya “overlay.html” tarayıcı kaynağı (saydam arka plan, uygulama görünümü) ya da tek tek .txt dosyaları “dosyadan oku” ile metin kaynağı olarak.", "M2Hub scrive i numeri su file – nessun server, nessuna porta. In OBS usa «overlay.html» come sorgente browser (sfondo trasparente, aspetto dell’app) oppure i singoli .txt come sorgente testo con «leggi da file»."],
        ["settings.stream.scope"] = ["Zeitraum für Truhen und Runs", "Period for chests and runs", "Sandık ve koşular için zaman aralığı", "Periodo per forzieri e run"],
        ["settings.stream.reset"] = ["Stream-Start auf jetzt setzen", "Set stream start to now", "Yayın başlangıcını şimdi yap", "Imposta ora l’inizio dello stream"],
        ["settings.stream.resetDone"] = ["Stream-Start steht auf jetzt – „Seit Stream-Start“ zählt ab hier.", "Stream start set to now – “since stream start” counts from here.", "Yayın başlangıcı şimdi – “yayın başından beri” buradan sayar.", "Inizio stream impostato ora – «dall’inizio dello stream» conta da qui."],
        ["settings.stream.open"] = ["Ordner öffnen", "Open folder", "Klasörü aç", "Apri cartella"],
        ["goals.kind.shop"] = ["Im Shop", "In the shop", "Dükkanda", "Nel negozio"],
        ["goals.shop.hint"] = ["Was im Shop liegt, zählt zusätzlich – aber nur der Teil, der nicht schon über die Runs gezählt ist. Trage darunter die Truhen ein, die im Betrag stecken; sie werden herausgerechnet. Den Gesamtwert rechnest du selbst zusammen – das Spiel zeigt ihn nirgends an.", "What sits in the shop counts on top – but only the part that is not already counted through the runs. Enter below the chests contained in the amount; they are deducted. You add up the total yourself – the game shows it nowhere.", "Dükkandaki miktar ek olarak sayılır – ama yalnızca koşular üzerinden henüz sayılmamış kısmı. Tutarın içindeki sandıkları aşağıya gir; onlar düşülür. Toplamı kendin hesaplarsın – oyun bunu hiçbir yerde göstermez.", "Ciò che è nel negozio conta in più – ma solo la parte non già conteggiata tramite le run. Inserisci sotto i forzieri contenuti nell’importo; vengono dedotti. Il totale lo sommi tu – il gioco non lo mostra da nessuna parte."],
        ["goals.shop.chests"] = ["Truhen", "Chests", "Sandık", "Forzieri"],
        ["goals.shop.price"] = ["Preis kk (leer = Tagespreis)", "Price kk (empty = daily price)", "Fiyat kk (boş = günün fiyatı)", "Prezzo kk (vuoto = prezzo del giorno)"],
        ["goals.shop.addChest"] = ["Truhen hinzufügen", "Add chests", "Sandık ekle", "Aggiungi forzieri"],
        ["goals.shop.counted"] = ["Davon schon gezählt: {0}", "Already counted: {0}", "Zaten sayılan: {0}", "Già conteggiato: {0}"],
        ["goals.shop.minus"] = ["abzüglich {0} Truhen ({1})", "minus {0} chests ({1})", "{0} sandık düşüldü ({1})", "meno {0} forzieri ({1})"],
        ["nav.timers"] = ["Timer-Fenster", "Timer window", "Zamanlayıcı penceresi", "Finestra timer"],
        ["timers.custom"] = ["Eigener Timer", "Own timer", "Kendi zamanlayıcın", "Timer personale"],
        ["settings.timers"] = ["Abklingzeiten über dem Spiel", "Cooldowns over the game", "Oyun üzerinde bekleme süreleri", "Tempi di recupero sopra il gioco"],
        ["settings.timers.enabled"] = ["Knopffenster zeigen", "Show the button window", "Düğme penceresini göster", "Mostra la finestra dei pulsanti"],
        ["settings.timers.hint"] = ["Ein kleines Fenster mit einem Knopf je Setup. Linksklick startet die Abklingzeit, ein zweiter startet sie neu, Rechtsklick hält sie an. Es liegt über allen Fenstern – Windows kennt kein „nur über dem Spiel“; mit dem Kreuz oder über diesen Knopf blendest du es aus. Gezogen wird an der Leiste oben.", "A small window with one button per setup. Left click starts the cooldown, a second one restarts it, right click stops it. It stays above every window – Windows has no “only over the game”; hide it with the cross or this button. Drag it by the bar on top.", "Her kurulum için bir düğme içeren küçük bir pencere. Sol tık bekleme süresini başlatır, ikincisi yeniden başlatır, sağ tık durdurur. Tüm pencerelerin üstünde durur – Windows’ta “yalnızca oyunun üstünde” diye bir şey yok; çarpı ile ya da bu düğmeyle gizle. Üstteki çubuktan sürükle.", "Una piccola finestra con un pulsante per ogni setup. Clic sinistro avvia il recupero, un secondo lo riavvia, clic destro lo ferma. Resta sopra ogni finestra – Windows non conosce «solo sopra il gioco»; nascondila con la croce o con questo pulsante. Trascinala dalla barra in alto."],
        ["settings.timers.counts"] = ["Setups je Lauf", "Setups per run", "Koşu başına kurulum", "Setup per run"],
        ["settings.timers.countsHint"] = ["Wie viele Charaktere du für diesen Lauf nebeneinander laufen lässt. 0 heißt: kein Knopf.", "How many characters you run side by side for this run. 0 means: no button.", "Bu koşu için yan yana kaç karakter kullanıyorsun. 0 = düğme yok.", "Quanti personaggi usi in parallelo per questa run. 0 significa: nessun pulsante."],
        ["settings.timers.custom"] = ["Eigene Timer", "Own timers", "Kendi zamanlayıcıların", "Timer personali"],
        ["settings.timers.customHint"] = ["Für alles, was zu keinem Lauf gehört – eigener Name, eigene Zeit.", "For anything that belongs to no run – own name, own time.", "Hiçbir koşuya ait olmayan her şey için – kendi adı, kendi süresi.", "Per tutto ciò che non appartiene a una run – nome e tempo propri."],
        ["settings.timers.name"] = ["Name", "Name", "Ad", "Nome"],
        ["settings.timers.minutesIn"] = ["Minuten", "Minutes", "Dakika", "Minuti"],
        ["settings.timers.minutes"] = ["{0} Minuten", "{0} minutes", "{0} dakika", "{0} minuti"],
        ["settings.timers.add"] = ["Hinzufügen", "Add", "Ekle", "Aggiungi"],
        ["settings.timers.delete"] = ["Timer löschen", "Delete timer", "Zamanlayıcıyı sil", "Elimina timer"],
        ["settings.timers.deleteAsk"] = ["„{0}“ wirklich löschen?", "Really delete “{0}”?", "“{0}” gerçekten silinsin mi?", "Eliminare davvero «{0}»?"],
        ["settings.timers.files"] = ["Abklingzeiten für OBS mitschreiben", "Write cooldowns for OBS", "Bekleme sürelerini OBS için yaz", "Scrivi i tempi di recupero per OBS"],
        ["settings.timers.filesHint"] = ["Schreibt je Timer eine .txt und eine fertige timer.html, im Sekundentakt – in einen eigenen Ordner „timer“ neben den Dateien der Einblendung.", "Writes one .txt per timer and a ready-made timer.html, once a second – into its own “timer” folder next to the overlay files.", "Her zamanlayıcı için bir .txt ve hazır bir timer.html’i saniyede bir yazar – yayın dosyalarının yanındaki kendi “timer” klasörüne.", "Scrive un .txt per timer e una timer.html pronta, ogni secondo – in una cartella «timer» accanto ai file dell’overlay."],
        ["settings.timers.size"] = ["Schriftgröße in der Stream-Karte", "Font size in the stream card", "Yayın kartındaki yazı boyutu", "Dimensione del testo nella scheda stream"],
        ["settings.tab.general"] = ["Allgemein", "General", "Genel", "Generale"],
        ["settings.tab.stream"] = ["Streaming", "Streaming", "Yayın", "Streaming"],
        ["settings.tab.app"] = ["Programm", "Program", "Program", "Programma"],
        ["settings.timers.sound"] = ["Ton, wenn eine Abklingzeit abläuft", "Sound when a cooldown ends", "Bekleme süresi dolunca ses", "Suono alla fine di un recupero"],
        ["settings.timers.soundHint"] = ["Hörbar neben dem Spiel, aber kein Alarm. Beim Umschalten hörst du den Ton einmal.", "Audible next to the game, but no alarm. You hear the sound once when switching.", "Oyunun yanında duyulur ama alarm değil. Seçerken sesi bir kez duyarsın.", "Udibile accanto al gioco, ma non un allarme. Senti il suono una volta quando lo scegli."],
        ["settings.timers.timeHint"] = ["Zeit als „5:30“ für 5 Minuten 30 Sekunden – eine blanke Zahl zählt als Minuten.", "Time as “5:30” for 5 minutes 30 seconds – a plain number counts as minutes.", "Süre “5:30” = 5 dakika 30 saniye – düz bir sayı dakika sayılır.", "Tempo come «5:30» per 5 minuti e 30 secondi – un numero semplice conta come minuti."],
        ["settings.timers.sound.soft"] = ["Weich", "Soft", "Yumuşak", "Morbido"],
        ["settings.timers.sound.chime"] = ["Glocke", "Chime", "Çan", "Campana"],
        ["settings.timers.sound.double"] = ["Doppelton", "Double beep", "Çift ton", "Doppio tono"],
        ["settings.timers.sound.gong"] = ["Gong", "Gong", "Gong", "Gong"],
        ["timers.chests"] = ["Truhen", "Chests", "Sandık", "Forzieri"],
        ["settings.timers.quick"] = ["Truhen direkt im Timer-Fenster eintragen", "Enter chests right in the timer window", "Sandıkları doğrudan zamanlayıcı penceresinde gir", "Inserisci i forzieri nella finestra timer"],
        ["settings.timers.quickHint"] = ["Unter den Timern steht je Lauf eine Reihe Knöpfe mit den Truhenzahlen, die er üblicherweise abwirft – Hydra 0 bis 5, Razador 8 bis 10, Schlangenrun 64. Ein Klick trägt den Lauf sofort für heute ein, ohne Tastatur.", "Below the timers, each run gets a row of buttons with the chest counts it usually drops – Hydra 0 to 5, Razador 8 to 10, Snake run 64. One click logs the run for today, no keyboard.", "Zamanlayıcıların altında her koşu için alışılmış sandık sayılarıyla bir düğme sırası – Hydra 0-5, Razador 8-10, Yılan koşusu 64. Bir tık, koşuyu bugüne kaydeder, klavye yok.", "Sotto i timer, ogni run ha una fila di pulsanti con i forzieri che di solito lascia – Hydra da 0 a 5, Razador da 8 a 10, Serpente 64. Un clic registra la run per oggi, senza tastiera."],
        ["patchnotes.title"] = ["Patch Notes", "Patch notes", "Sürüm notları", "Note di rilascio"],
        ["patchnotes.version"] = ["Patch {0}", "Patch {0}", "Sürüm {0}", "Patch {0}"],
        ["patchnotes.close"] = ["Alles klar", "Got it", "Tamam", "Ho capito"],
