        ["settings.start.sections"] = ["Abschnitte wählen und ordnen", "Choose and order sections", "Bölümleri seç ve sırala", "Scegli e ordina le sezioni"],
        ["settings.stream.details"] = ["Zeitraum, zweite Karte und Ordner", "Period, second card and folder", "Zaman aralığı, ikinci kart ve klasör", "Periodo, seconda scheda e cartella"],
