        ["settings.update"] = ["Aktualisierung", "Updates", "Güncelleme", "Aggiornamenti"],
        ["settings.update.check"] = ["Beim Start nach einer neueren Version sehen", "Check for a newer version on start", "Açılışta yeni sürüm ara", "Cerca una nuova versione all’avvio"],
        ["settings.update.hint"] = ["Auf Knopfdruck lädt die App die neue Version, ersetzt sich selbst und startet neu.", "At the press of a button the app downloads the new version, replaces itself and restarts.", "Tek tuşla uygulama yeni sürümü indirir, kendini değiştirir ve yeniden başlar.", "Con un clic l’app scarica la nuova versione, si sostituisce e si riavvia."],
        ["settings.update.now"] = ["Jetzt nach Update sehen", "Check for updates now", "Şimdi güncelleme ara", "Cerca aggiornamenti ora"],
        ["settings.update.page"] = ["Release-Seite öffnen", "Open release page", "Sürüm sayfasını aç", "Apri la pagina delle release"],
        ["settings.update.dev"] = ["Test-Updates (M2hubDev)", "Test updates (M2hubDev)", "Test güncellemeleri (M2hubDev)", "Aggiornamenti di test (M2hubDev)"],
        ["settings.update.devHint"] = ["Mit einem Zugangsschlüssel zum Dev-Repo sucht die App auch nach dem neuesten Test-Build und tauscht sich auf Wunsch darauf aus. Der Schlüssel bleibt nur lokal auf diesem Rechner.", "With an access token for the dev repo the app also checks for the latest test build and swaps itself to it on request. The token stays local to this computer.", "Dev deposuna ait bir erişim anahtarıyla uygulama en yeni test yapısını da arar ve isteğe bağlı olarak ona geçer. Anahtar yalnızca bu bilgisayarda kalır.", "Con un token di accesso al repo dev l’app cerca anche l’ultima build di test e vi si aggiorna su richiesta. Il token resta locale su questo computer."],
        ["settings.update.devPlaceholder"] = ["GitHub-Token (nur lesend)", "GitHub token (read-only)", "GitHub anahtarı (salt okunur)", "Token GitHub (sola lettura)"],
